const cameras = $input.all().map(i => i.json);
const cfg = $('Config').first().json;
const limite = Number(cfg.limiteTentativas) || 3;
const elegiveis = cameras.filter(c => { const st = String(c.status || '').trim(); const tent = Number(c.tentativas) || 0; return (st === 'Pendente' || st === 'Aguardando resposta' || st === 'offline' || st === 'notificado') && tent < limite; });
const grupos = {};
for (const c of elegiveis) {
  const tel = String(c.responsavel_telefone || '').replace(/\D/g, '');
  if (!tel) continue;
  if (!grupos[tel]) grupos[tel] = { telefone: tel, nome: c.responsavel_nome || '', cameras: [], maxTent: 0 };
  grupos[tel].cameras.push(c);
  grupos[tel].maxTent = Math.max(grupos[tel].maxTent, Number(c.tentativas) || 0);
}
const out = [];
for (const g of Object.values(grupos)) {
  const tentativa = g.maxTent + 1;
  const template = g.maxTent > 0 ? cfg.templateFollowup : cfg.templateInicial;
  const lista = g.cameras.map(c => (c.camera_nome + ' (' + (c.local || '') + ')').trim()).join('; ');
  const components = template === cfg.templateFollowup ? [{ type: 'body', parameters: [ { type: 'text', text: g.nome }, { type: 'text', text: lista }, { type: 'text', text: String(tentativa) }, { type: 'text', text: String(limite) } ] }] : [{ type: 'body', parameters: [ { type: 'text', text: g.nome }, { type: 'text', text: lista } ] }];
  const payload = { messaging_product: 'whatsapp', to: g.telefone, type: 'template', template: { name: template, language: { code: 'pt_BR' }, components: components } };
  out.push({ json: { telefone: g.telefone, nome: g.nome, listaTexto: lista, tentativa, template, payload, cameras: g.cameras } });
}
return out;

const out = [];
const now = new Date().toISOString();
for (const it of $input.all()) {
  const g = it.json;
  for (const c of (g.cameras || [])) {
    out.push({ json: { id: c.id, status: 'Aguardando resposta', tentativas: (Number(c.tentativas) || 0) + 1, ultima_cobranca: now, observacoes: c.observacoes || '' } });
  }
}
return out;

const grupos = $('Filtrar e agrupar').all();
const out = [];
for (const g of grupos) {
  const j = g.json;
  out.push({ json: { timestamp: new Date().toISOString(), camera_id: (j.cameras || []).map(c => c.id).join(','), camera_nome: (j.cameras || []).map(c => c.camera_nome).join(', '), responsavel_telefone: j.telefone, acao: 'COBRANCA_ENVIADA', detalhe: 'Template ' + j.template + '; tentativa ' + j.tentativa, status_anterior: 'Pendente', status_novo: 'Aguardando resposta' } });
}
return out;
